                    algorithm.Operation(empty=10, fill=30, creators=(0,)),
                    (0, 1),
                    None,
                    1,
                ),
                vanish_workloads.Step(
                    algorithm.Operation(empty=30, fill=10, creators=(0,)),
                    (0, 1),
                    None,
                    1,
                ),
            ]
        )
    experiment.verify(experiment.Scenario(steps, transitive, retentions))


